-- Migration 173: create generated_files table for agent-produced documents
-- Tracks Excel/Word documents generated by agents, their GCS location,
-- versioning, and optional connector sync status.

BEGIN;

CREATE TABLE generated_files (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id         UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  agent_id          UUID NOT NULL REFERENCES internal_agents(id) ON DELETE CASCADE,
  conversation_id   UUID REFERENCES agent_chat_threads(id) ON DELETE SET NULL,
  filename          TEXT NOT NULL,
  base_name         TEXT NOT NULL,
  version           INTEGER NOT NULL DEFAULT 1,
  output_type       TEXT NOT NULL CHECK (output_type IN ('xlsx', 'docx', 'docx_redlined')),
  gcs_path          TEXT NOT NULL,
  size_bytes        BIGINT,
  connector_id      UUID,
  connector_file_id TEXT,
  connector_path    TEXT,
  web_view_url      TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX generated_files_agent_idx ON generated_files(agent_id);
CREATE INDEX generated_files_conversation_idx ON generated_files(conversation_id);
CREATE INDEX generated_files_base_name_idx ON generated_files(agent_id, base_name);

COMMIT;
